out=Path(__file__).parent
with sync_playwright() as p:
 b=p.chromium.launch(channel='chrome',headless=True);page=b.new_page(viewport={'width':390,'height':667},device_scale_factor=1,reduced_motion='reduce');page.goto('http://127.0.0.1:5178');page.wait_for_function('document.querySelector("#scene").readyState>=3');page.locator('.lab summary').click();page.locator('#long-line').check();page.locator('.lab summary').click();page.mouse.wheel(0,400);page.wait_for_timeout(200);before=page.locator('#scene').bounding_box();assert before['y']<0;r=page.locator('#record').bounding_box();assert r['y']>0 and r['y']+r['height']<667;page.mouse.click(r['x']+r['width']/2,r['y']+r['height']/2);expect(page.locator('#capture-badge')).to_be_visible();after=page.locator('#scene,#dialogue,#capture-badge').evaluate_all('(es)=>es.map(e=>({id:e.id,rect:e.getBoundingClientRect().toJSON()}))');assert all(e['rect']['top']>=0 and e['rect']['bottom']<=667 for e in after);assert page.locator('#scene').evaluate('(e)=>!e.paused');page.screenshot(path=str(out/'v2-review-direct-capture-restores-context.png'));(out/'v2-direct-capture-check.json').write_text(json.dumps({'before':before,'after':after,'reducedMotion':True,'captureImmediatePlaying':True},indent=2),encoding='utf-8');print(after);b.close()
